package com.cryptoloan.notification.adapters.inout;import com.cryptoloan.notification.domain.model.Notification;import com.cryptoloan.notification.domain.port.out.NotificationPorts.LivePublisher;import java.io.IOException;import java.util.concurrent.*;import org.springframework.stereotype.Component;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;@Component public class SseNotificationAdapter implements LivePublisher{private final ConcurrentMap<String,CopyOnWriteArrayList<SseEmitter>>clients=new ConcurrentHashMap<>();public SseEmitter subscribe(String email){SseEmitter e=new SseEmitter(0L);clients.computeIfAbsent(email,k->new CopyOnWriteArrayList<>()).add(e);e.onCompletion(()->remove(email,e));e.onTimeout(()->remove(email,e));return e;}public void publish(Notification n){for(SseEmitter e:clients.getOrDefault(n.recipient(),new CopyOnWriteArrayList<>()))try{e.send(SseEmitter.event().name(n.type()).data(n));}catch(IOException ex){remove(n.recipient(),e);}}private void remove(String email,SseEmitter e){clients.getOrDefault(email,new CopyOnWriteArrayList<>()).remove(e);}}

